import {computed, getCurrentInstance, onMounted, ref, toValue, useId, watch} from 'vue'
import {onClickOutside, useEventListener} from '@vueuse/core'
import {isPlainObject} from 'vuepress/shared'

function useExpand(defaultExpand = true) {
  const expanded = ref(defaultExpand)
  function toggle() {
    expanded.value = !expanded.value
  }
  return [expanded, toggle]
}
function useResources(el, config) {
  const resources = computed(() => {
    const conf = toValue(config)
    if (!conf) return []
    return [
      {
        name: 'JavaScript',
        items: conf.jsLib?.map((url) => ({
          name: normalizeName(url),
          url,
        })),
      },
      {
        name: 'CSS',
        items: conf.cssLib?.map((url) => ({
          name: normalizeName(url),
          url,
        })),
      },
    ].filter((i) => i.items?.length)
  })
  function normalizeName(url) {
    return url.slice(url.lastIndexOf('/') + 1)
  }
  const showResources = ref(false)
  function toggleResources() {
    showResources.value = !showResources.value
  }
  onClickOutside(el, () => {
    showResources.value = false
  })
  return {
    resources,
    showResources,
    toggleResources,
  }
}
function useFence(fence, config) {
  const data = ref({
    js: '',
    css: '',
    html: '',
    jsType: '',
    cssType: '',
  })
  onMounted(() => {
    if (!fence.value) return
    const conf = toValue(config)
    data.value.html = conf?.html ?? ''
    const els = Array.from(fence.value.querySelectorAll('div[class*="language-"]'))
    for (const el of els) {
      const lang = el.className.match(/language-(\w+)/)?.[1] ?? ''
      const content = el.querySelector('pre')?.textContent ?? ''
      if (lang === 'js' || lang === 'javascript') {
        data.value.js = content
        data.value.jsType = 'js'
      }
      if (lang === 'ts' || lang === 'typescript') {
        data.value.js = content
        data.value.jsType = 'ts'
      }
      if (
        lang === 'css' ||
        lang === 'scss' ||
        lang === 'less' ||
        lang === 'stylus' ||
        lang === 'styl'
      ) {
        data.value.css = content
        data.value.cssType = lang === 'styl' ? 'stylus' : lang
      }
    }
  })
  return data
}
function useNormalDemo(draw, title, config) {
  const current = getCurrentInstance()
  const id = useId()
  const isDark = computed(() => current?.appContext.config.globalProperties.$isDark?.value ?? false)
  const height = ref('100px')
  const templateId = `VPDemoNormalDraw${id}`
  const html = ref('')
  watch(
    [config, title],
    () => {
      html.value = createHTMLTemplate(
        toValue(title) || 'Demo',
        templateId,
        toValue(config),
        isDark.value ? 'dark' : 'light',
      )
    },
    {immediate: true},
  )
  function syncTheme() {
    draw.value?.contentWindow?.postMessage(
      {
        type: `${templateId}-theme`,
        theme: isDark.value ? 'dark' : 'light',
      },
      '*',
    )
  }
  watch(isDark, syncTheme)
  onMounted(() => {
    useEventListener('message', (event) => {
      if (event.source !== draw.value?.contentWindow) return
      const data = parseData(event.data)
      if (data.type === templateId && typeof data.height === 'number')
        height.value = `${data.height + 5}px`
    })
  })
  return {
    id,
    height,
    html,
    syncTheme,
  }
}
const RESOURCE_PROTOCOLS = ['http:', 'https:']
const HTML_ESCAPE = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}
function escapeHtml(value) {
  return value.replace(/[&<>"']/g, (char) => HTML_ESCAPE[char])
}

function isSafeResourceUrl(url) {
  if (typeof url !== 'string' || url.trim() === '') return false
  try {
    return RESOURCE_PROTOCOLS.includes(new URL(url, 'http://a.com').protocol)
  } catch {
    return false
  }
}
function createHTMLTemplate(title, id, config, theme = 'light') {
  const {cssLib = [], jsLib = [], html, css, script} = config || {}
  const stylesheet = cssLib
    .filter(isSafeResourceUrl)
    .map((url) => `<link rel="stylesheet" href="${escapeHtml(url)}">`)
    .join('')
  const scripts = jsLib
    .filter(isSafeResourceUrl)
    .map((url) => `<script src="${escapeHtml(url)}"><\/script>`)
    .join('')
  const typeId = JSON.stringify(id)
  const themeId = JSON.stringify(`${id}-theme`)
  return `<!DOCTYPE html>
<html data-theme="${theme}">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>${escapeHtml(title)}</title>
    ${stylesheet}${scripts}
    <style>${css}</style>
  </head>
  <body>
    ${html}
    <script>;(function(){${script}})();<\/script>
    <script>;(function(){
  window.addEventListener('message', function (event) {
    var data = event.data
    if (event.source !== window.parent || !data || data.type !== ${themeId} || (data.theme !== 'dark' && data.theme !== 'light'))
      return
    document.documentElement.dataset.theme = data.theme
  })
  function postHeight() {
    var height = Math.ceil(document.documentElement.getBoundingClientRect().height)
    window.parent?.postMessage({ type: ${typeId}, height }, '*')
  }
  postHeight()
  if (typeof window.ResizeObserver === 'undefined')
    return
  var resizeObserver = new ResizeObserver(postHeight)
  resizeObserver.observe(document.documentElement)
})();<\/script>
  </body>
</html>`
}
function parseData(data) {
  try {
    if (typeof data === 'string') return JSON.parse(data)
    else if (isPlainObject(data)) return data
    return {}
  } catch {
    return {}
  }
}

export {parseData, useExpand, useFence, useNormalDemo, useResources}
